import React from "react";
import './Login.css';

function login() {
    return ( 
        <div className="LoginBox">
            <img src="logo.png"></img>
            <p>Login to kite</p>
            <form>
                <input placeholder="Enter username" />
                <input placeholder="Enter Password" />
            </form>
        </div>
     );
}

export default login;
